import logging
import uuid

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
        except Exception as exc:
            return self._handle_unexpected_error(user, item, quantity, exc, is_admin)

        return (
            200,
            f"Thank you, {user}! Your order of {quantity} x {item} has been placed. "
            f"Reservation id: {reservation_id}.",
        )

    def _handle_unexpected_error(self, user, item, quantity, exc, is_admin):
        reference = uuid.uuid4().hex
        logger.error(
            "Unexpected error while placing order (reference=%s, user=%s, item=%s, quantity=%s)",
            reference,
            user,
            item,
            quantity,
            exc_info=exc,
        )
        message = (
            f"Sorry, something went wrong while processing your order. "
            f"Please contact support and quote reference code: {reference}."
        )
        if is_admin:
            message += f" (Details: {type(exc).__name__}: {exc})"
        return (500, message)
